from math import pi, fabs


class TriCalculator:

    DEGREES_TO_RADIANS = pi / 180
    TAYLOR_COS_PRECISION = 50
    SIN_TAYLOR_EPSILON = 1e-15
    RESULT_PRECISION = 10

    def __init__(self):
        pass

    def cos(self, x):
        return round(self._taylor_cos(x, self.TAYLOR_COS_PRECISION), self.RESULT_PRECISION)

    def factorial(self, a):
        result = 1
        for i in range(2, a + 1):
            result *= i
        return result

    def _taylor_cos(self, x, n):
        x_rad = self._degrees_to_radians(x)
        result = 1.0
        for k in range(1, n):
            term = (x_rad ** (2 * k)) / self.factorial(2 * k)
            if k % 2 != 0:
                result -= term
            else:
                result += term
        return result

    def sin(self, x):
        x_rad = self._degrees_to_radians(x)
        total = 0.0
        term = x_rad
        n = 1

        while fabs(term) >= self.SIN_TAYLOR_EPSILON:
            total += term
            n += 1
            term = -term * x_rad * x_rad / (2 * n - 1) / (2 * n - 2)
        return round(total, self.RESULT_PRECISION)

    def tan(self, x):
        cos_value = self.cos(x)
        if cos_value != 0:
            return self.sin(x) / cos_value
        return False

    def _degrees_to_radians(self, x):
        return x * self.DEGREES_TO_RADIANS
